package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.mapper.SourceReadMapper;
import java.math.BigInteger;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Real approved configuration and current transmission rights for private physically read EVAL inputs. */
public final class FormalEvaluationInvocationContext {
 private final ModelConfigurationService models;private final ModelEligibilityAuthority eligibility;private final AgentExecutionPolicyAuthority policies;
 private final ResourceReadAuthority resources;private final SourceReadAuthority sources;private final SourceReadMapper sourceRows;private final DependencyLineage lineage;
 private final FormalCapabilityIdentityAuthority capabilities;private final RunTokenAuthoritySchema runtime;private final RuntimeRetentionAuthority retention;
 private final RuntimeObjectTransport transport;private final FormalInvocationSchema schema;private final PermissionSchema json;private final JdbcTemplate db;
 public FormalEvaluationInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,AgentExecutionPolicyAuthority policies,ResourceReadAuthority resources,SourceReadAuthority sources,SourceReadMapper sourceRows,DependencyLineage lineage,FormalCapabilityIdentityAuthority capabilities,RunTokenAuthoritySchema runtime,RuntimeRetentionAuthority retention,RuntimeObjectTransport transport,FormalInvocationSchema schema,PermissionSchema json){this.models=models;this.eligibility=eligibility;this.policies=policies;this.resources=resources;this.sources=sources;this.sourceRows=sourceRows;this.lineage=lineage;this.capabilities=capabilities;this.runtime=runtime;this.retention=retention;this.transport=transport;this.schema=schema;this.json=json;db=new JdbcTemplate(data);db.setQueryTimeout(5);}
 record State(JsonNode model,JsonNode request,JsonNode dependencies,JsonNode send,JsonNode body,PermissionProtocol.Basis price){}
 State require(FormalEvaluationNodeRuntime.Session session,FormalInvocationSourceOriginals.Read priceRead)throws Exception {
  session.requireExecutionCurrent();var lease=session.lease();var a=lease.admission();var j=lease.job();var n=lease.node().node();var input=lease.input();input.requireCurrent(a);
  if(n.model()==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var policy=policies.requireByVersion(a,n.cell().policy().version_id(),n.cell().policy().content_sha256(),j.projectId(),j.classification(),"RUN_CREATION");var definition=policy.definition();
  var binding=policy.requireNode(n.nodeKind(),n.role(),lease.workerService(),definition.worker().audience());if(!n.model().equals(binding.modelVersion())||!n.tokenizer().equals(binding.tokenizerVersion())||!n.parametersSha256().equals(schema.hash(binding.generationParameters())))bad();
  var fixed=models.requireCurrentExternal(a,n.model().version_id(),"RUN_CREATION",j.projectId());var model=(ModelConfigurationProtocol.Definition)fixed.definition();var enabled=eligibility.require(a,n.model().version_id(),"RUN_CREATION",j.projectId());if(!n.model().content_sha256().equals(enabled.contentSha256()))bad();
  enabled.requireParameters(binding.generationParameters());enabled.requireDataUse(j.classification(),definition.region(),definition.trainingAllowed());if(!"EVALUATION".equals(binding.generationParameters().required("purpose").asText()))bad();
  var role=capabilities.require(a,n.role(),"ROLE",j.projectId(),"EVALUATION_RESULTS");var roleScope=runtime.read("RoleScope",json.canonical(role.canonicalDefinition().required("request").required("tool_scope")));
  var modelScope=new PermissionProtocol.Scope(j.tenantId(),fixed.project_id(),"CONFIGURATION",fixed.config_id());var grant=resources.require(a,modelScope,"model.send","EVALUATION_RESULTS");requireRole(roleScope,new RunTokenAuthoritySchema.Permission(modelScope,"model.send","EVALUATION_RESULTS"));
  var sent=json.object();sent.set("model_send",AgentPublicationWitness.tree(grant));sent.set("independent_context",input.context().requireModelSend(a,model.provider()));var content=sent.putObject("content");
  // Independently authorize each transmitted source ancestry under its actual purpose.
  // Tool/tokenizer package provenance is checked by input.requireCurrent, but their executable bytes are not sent.
  authorizeGraph(a,j,n.cell().input(),definition.businessPurpose(),input.evidence().required("source_snapshot"),definition,model,enabled,roleScope,content);
  var prompt=input.evidence().required("prompt_original");authorizeGraph(a,j,new PermissionProtocol.Basis(text(prompt,"artifact_id"),text(prompt,"sha256")),"AGENT_PUBLICATION",input.evidence().required("prompt_source_snapshot"),definition,model,enabled,roleScope,content);
  if(input.evidence().has("planning_original")){var planning=input.evidence().required("planning_original");authorizeGraph(a,j,new PermissionProtocol.Basis(text(planning,"artifact_id"),text(planning,"sha256")),definition.businessPurpose(),input.evidence().required("source_snapshot"),definition,model,enabled,roleScope,content);}
  if(input.evidence().has("case_original")){var original=input.evidence().required("case_original");authorizeGraph(a,j,new PermissionProtocol.Basis(text(original,"artifact_id"),text(original,"sha256")),definition.businessPurpose(),input.evidence().required("source_snapshot"),definition,model,enabled,roleScope,content);}
  var tokenization=input.evidence().required("tokenization");if(!input.sha256().equals(text(tokenization,"input_sha256"))||!n.tokenizer().content_sha256().equals(text(tokenization,"executable_sha256")))bad();var count=new BigInteger(text(tokenization,"token_count"));var output=binding.generationParameters().required("max_output_tokens").bigIntegerValue();if(count.signum()<0||output.signum()<=0||count.add(output).compareTo(new BigInteger(model.limits().context_window()))>0)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);
  var exact=schema.parse(new String(input.bytes(),java.nio.charset.StandardCharsets.UTF_8));SchemaCatalogue.fromClasspath().validate("simulation-execution",exact,"ExactInput");var body=FormalInvocationSendPreparation.providerBody(json.tree(model),binding.generationParameters(),exact);
  var request=json.object().put("schema_version","1.0.0").put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION").put("node_kind",n.nodeKind()).put("model_config_revision",n.model().version_id()).put("business_purpose","EVALUATION_RESULTS").put("maximum_input_tokens",count.toString());
  var artifact=one(db.query("SELECT object_key,object_version,sha256,CAST(size_bytes AS CHAR),media_type FROM artifact WHERE tenant_id=? AND artifact_id=? LIMIT 2",(r,i)->new InterfaceProtocol.ObjectRef(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)),j.tenantId(),input.artifact().artifactId()));String coverage=ObjectContentPaging.rangeDigest(ObjectContentPaging.objectDigest(artifact),0,Long.parseLong(artifact.sizeBytes()));request.set("exact_input",json.tree(new CommonProtocol.ArtifactRef(input.artifact().artifactId(),input.sha256(),input.artifact().schemaRef(),new CommonProtocol.Coverage(coverage,coverage,true,null))));
  var admission=schema.parse(j.canonicalAdmission());request.set("enterprise_budget_basis",admission.required("root_request").required("enterprise_budget"));request.set("parent_budget_basis",admission.required("root_request").required("parent_budget"));request.set("request_parameters",binding.generationParameters());request.set("prompt_basis",input.evidence().required("prompt"));request.set("tokenizer_basis",json.tree(n.tokenizer()));
  var keep=retention.requireForRun(a,j.projectId(),j.classification(),"RUN_CREATION");var retentionPins=json.object().put("policy_revision",keep.policyRevision()).put("content_sha256",keep.contentSha256());retentionPins.set("terms",keep.terms());var created=one(db.query("SELECT created_at FROM system_job_run WHERE tenant_id=? AND run_id=? LIMIT 2",(r,i)->r.getTimestamp(1).toInstant(),j.tenantId(),j.runId()));
  var deps=json.object();deps.set("model",json.tree(fixed));deps.set("model_eligibility",json.tree(enabled.safeReplayBinding()));deps.set("policy",json.tree(definition));deps.set("policy_authorizations",policy.authorizations());deps.set("send_authorizations",sent);deps.set("role_authorizations",role.authorizations());deps.set("output_storage",json.tree(transport.storageBinding()));deps.set("retention",retentionPins);deps.set("output_retention",TaskInvocationOutputPolicy.forRun(j.runId(),created,retentionPins));
  if(priceRead!=null){priceRead.requireCurrent(a);if(!model.price_basis().version_id().equals(priceRead.sourceVersion())||!model.price_basis().content_sha256().equals(priceRead.contentSha256()))bad();var price=schema.read("PriceProfile",priceRead.bytes(),16777216);for(String key:List.of("provider","model_id","model_version","currency"))if(!json.tree(model).required(key).equals(price.required(key)))bad();deps.set("price",price);deps.put("price_authorization_sha256",priceRead.authorizationSha256());}
  enabled.requireUnchanged();role.requireUnchanged();policy.requireUnchanged();keep.requireUnchanged();session.requireExecutionCurrent();return new State(json.tree(fixed),request,deps,sent,body,model.price_basis());
 }
 private void authorizeGraph(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job job,PermissionProtocol.Basis root,String purpose,JsonNode snapshot,AgentExecutionPolicyProtocol.Definition policy,ModelConfigurationProtocol.Definition model,ModelEligibilityAuthority.Verified enabled,JsonNode role,ObjectNode out)throws Exception {
  var graph=lineage.inspect(root.version_id(),new DependencyLineage.Limits(512,2048));if(!root.content_sha256().equals(graph.versions().get(root.version_id()).contentSha256()))bad();
  for(var version:graph.versions().values()){var rows=sourceRows.source(version.id());if(rows.size()>1)bad();if(rows.isEmpty())continue;var source=rows.get(0);String snapshotId=text(snapshot,"version_id");String parse=one(db.query("SELECT parse_version FROM scope_member WHERE tenant_id=? AND project_id=? AND snapshot_id=? AND source_version=? LIMIT 2",(r,i)->r.getString(1),job.tenantId(),job.projectId(),snapshotId,source.sourceVersion()));var proof=sources.require(a,new SourceReadProtocol.ReadRequirement(source.sourceVersion(),source.rightsRevision(),job.projectId(),snapshotId,parse,null,SourceReadProtocol.Use.MODEL_SEND,purpose,policy.environment(),policy.region(),model.provider()));enabled.requireDataUse(source.classification(),policy.region(),policy.trainingAllowed());var scope=new PermissionProtocol.Scope(job.tenantId(),source.ownerProjectId(),"SOURCE",source.sourceId());for(String action:List.of("source.read","source.external.process"))requireRole(role,new RunTokenAuthoritySchema.Permission(scope,action,purpose));requireRole(role,new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(job.tenantId(),job.projectId(),"PROJECT",job.projectId()),"project.read",purpose));out.set(purpose+"/"+version.id(),AgentPublicationWitness.tree(proof));}
 }
 private void requireRole(JsonNode role,RunTokenAuthoritySchema.Permission permission){for(var p:role.required("permissions"))if(p.equals(json.tree(permission)))return;throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
 private static String text(JsonNode n,String k){return FormalEvaluationInvocationRecords.text(n,k);}private static <T>T one(List<T> r){if(r.size()!=1)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
